/// @nodoc
final class radio_s extends ffi.Opaque {}

/// Enumeration of radio state.
///
/// **Since Tizen:**
/// - 2.3
/// @nodoc
abstract class radio_state_e {
  /// < Ready to play or scan
  static const int RADIO_STATE_READY = 0;

  /// < Playing the audio from the tuner
  static const int RADIO_STATE_PLAYING = 1;

  /// < Scanning/Searching for the next station signal that starts from a given starting frequency
  static const int RADIO_STATE_SCANNING = 2;
}

/// Enumeration of error codes for the radio.
///
/// **Since Tizen:**
/// - 2.3
/// @nodoc
abstract class radio_error_e {
  /// < Successful
  static const int RADIO_ERROR_NONE = 0;

  /// < Out of memory
  static const int RADIO_ERROR_OUT_OF_MEMORY = -12;

  /// < Invalid parameter
  static const int RADIO_ERROR_INVALID_PARAMETER = -22;

  /// < Invalid operation
  static const int RADIO_ERROR_INVALID_OPERATION = -38;

  /// < Invalid state
  static const int RADIO_ERROR_INVALID_STATE = -26869759;

  /// < Sound policy error
  static const int RADIO_ERROR_SOUND_POLICY = -26869758;

  /// < No Antenna error (Since 2.4)
  static const int RADIO_ERROR_NO_ANTENNA = -26869757;

  /// < Permission denied
  static const int RADIO_ERROR_PERMISSION_DENIED = -13;

  /// < Not supported
  static const int RADIO_ERROR_NOT_SUPPORTED = -1073741822;
}

/// Enumeration of radio interrupted type.
///
/// **Since Tizen:**
/// - 2.3
/// @nodoc
abstract class radio_interrupted_code_e {
  /// < Interrupted by a resource conflict
  static const int RADIO_INTERRUPTED_BY_RESOURCE_CONFLICT = 4;
}

